use std::collections::HashMap;

fn two_sum(nums: Vec<i32>, target: i32) -> Option<(usize, usize)> {
    // Map from a number to its first-occurring index in `nums`.
    let mut first_index: HashMap<i32, usize> = HashMap::new();
    // Track the best (i, j) pair found so far in lex order.
    let mut best_pair: Option<(usize, usize)> = None;
    // Work in i64 to avoid overflow when computing complements.
    let t64 = target as i64;

    for (j, &v) in nums.iter().enumerate() {
        let v64 = v as i64;
        // Compute the required complement in i64.
        let w64 = t64 - v64;
        // Only consider it if it fits in i32.
        if w64 >= i32::MIN as i64 && w64 <= i32::MAX as i64 {
            let w = w64 as i32;
            if let Some(&i) = first_index.get(&w) {
                // We have a candidate pair (i, j) with i < j.
                let candidate = (i, j);
                best_pair = match best_pair {
                    None => Some(candidate),
                    Some((bi, bj)) => {
                        // Compare lexicographically.
                        if candidate.0 < bi || (candidate.0 == bi && candidate.1 < bj) {
                            Some(candidate)
                        } else {
                            Some((bi, bj))
                        }
                    }
                };
            }
        }
        // Record the first occurrence of v.
        first_index.entry(v).or_insert(j);
    }

    best_pair
}

