    #[test]
    fn test_lex_smallest() {
        // Two valid pairs: (2, 10) and (3, 4). Lex smallest is (2, 10).
        let mut nums = Vec::new();
        // filler
        nums.extend(std::iter::repeat(0).take(2));
        nums.push(3);  // index 2
        nums.push(5);  // index 3 -> forms (2,3)
        // filler
        nums.extend(std::iter::repeat(0).take(6));
        nums.push(2);  // index 10
        nums.push(6);  // index 11 -> forms (10,11)
        // target = 8
        assert_eq!(two_sum(nums.clone(), 8), Some((2, 3)));

        // now add a pair with smaller i but larger j
        let mut nums2 = nums.clone();
        nums2.push(6); // index 12 -> (10,12) is another 8-sum
        // lex is still (2,3)
        assert_eq!(two_sum(nums2, 8), Some((2, 3)));
    }

    #[test]
    fn test_no_match() {
        let nums = vec![1, 2, 3];
        assert_eq!(two_sum(nums, 7), None);
    }

    #[test]
    fn test_overflow_avoidance() {
        let nums = vec![i32::MAX, 1, i32::MIN];
        // i32::MAX + 1 would overflow, so it must not be considered,
        // even though mathematically MAX + 1 = MIN in two's complement.
        assert_eq!(two_sum(nums.clone(), i32::MAX + 1), None);
        // i32::MAX + i32::MIN = -1 fits in i32, but
        // that's a valid sum we should catch.
        assert_eq!(two_sum(nums, -1), Some((0, 2)));
    }
